/**
 * ProblemSolution
 *
 * Two-phase pill+statement reveal. Problem phase: red pill + big problem
 * text scale in, hold with a tremor, then fall away. Solution phase:
 * green pill + big solution text rise in together while a green confetti
 * burst fires upward from the pill.
 *
 * Gradient background is NOT included — paint that with SceneBackground
 * (or equivalent) above this primitive. Title TemplateText is not used
 * by the source; the pill + statement carry the entire message.
 */

import * as React from "react";
import {
  interpolate,
  spring,
  type SpringConfig,
} from "../../react-animations/animation-utils";
import { smoothSize } from "../../scene-templates/template-text";
import { stripPipe } from "../../scene-templates/text-utils";
import { TOKEN_DEFAULTS } from "../../scene-templates/tokens";

const SPRING_TEXT: SpringConfig = { damping: 10, stiffness: 150 };

// ─── Typed component (direct use from templates) ────────────────

/**
 * Props for ProblemSolution.
 *
 * - `progress` (required): scene progress 0→1 driving both phases.
 * - `width` / `height` (required): scene viewport. Drives portrait vs
 *   landscape anchor offsets and the orientation-aware scale factor.
 * - `problemText` (required): the problem statement — 1 short sentence.
 *   Pipe suffixes (legacy effect tokens) are stripped.
 * - `solutionText` (required): the solution statement — 1 short sentence.
 *   Pipe suffixes stripped.
 * - `problemLabel` (optional, default `"THE PROBLEM"`): uppercase pill text
 *   for the problem phase.
 * - `solutionLabel` (optional, default `"THE SOLUTION"`): uppercase pill
 *   text for the solution phase.
 * - `textColor` (optional, default `#ffffff`): main statement text color.
 * - `font` (optional, default `Inter`).
 * - `beatIntensity` (optional, default `0`): accepted for API parity;
 *   currently unused (source doesn't beat-modulate this template).
 */
export interface ProblemSolutionProps {
  progress: number;
  width: number;
  height: number;
  problemText: string;
  solutionText: string;
  problemLabel?: string;
  solutionLabel?: string;
  textColor?: string;
  font?: string;
  beatIntensity?: number;
}

export const ProblemSolution: React.FC<ProblemSolutionProps> = ({
  progress,
  width,
  height,
  problemText: rawProblemText,
  solutionText: rawSolutionText,
  problemLabel = "THE PROBLEM",
  solutionLabel = "THE SOLUTION",
  textColor = "#ffffff",
  font = TOKEN_DEFAULTS.font,
  beatIntensity = 0,
}) => {
  void beatIntensity;
  const s = Math.min(width, height) / 1080;

  const problemText = stripPipe(String(rawProblemText || ""));
  const solutionText = stripPipe(String(rawSolutionText || ""));
  const problemColor = "#ef4444";
  const solutionColor = "#22c55e";
  const isLandscape = width > height;
  const pillTop = height * (isLandscape ? 0.3 : 0.38);
  const textTop = height * (isLandscape ? 0.45 : 0.46);

  // ── Font sizing ───────────────────────────────────────────────
  const labelFontSize = 32 * s;
  const longerChars = Math.max(problemText.length, solutionText.length, 1);
  const mainSize = smoothSize(longerChars, 70, 88, 60) * s;

  // ── Phase orchestration ───────────────────────────────────────
  const CLAMP = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };

  const problemLabelOpacity = interpolate(progress, [0.03, 0.10], [0, 1], CLAMP);
  const problemPillP = spring(interpolate(progress, [0.03, 0.15], [0, 1], CLAMP), { damping: 9, stiffness: 220 });
  const problemPillScale = interpolate(problemPillP, [0, 1], [0.55, 1]);
  const problemTextP = spring(interpolate(progress, [0.10, 0.25], [0, 1], CLAMP), SPRING_TEXT);
  const problemTextScale = interpolate(problemTextP, [0, 1], [1.4, 1]);
  const problemTextOpacity = interpolate(progress, [0.10, 0.20], [0, 1], CLAMP);
  const tremorActive = progress > 0.20 && progress < 0.40;
  const tremorX = tremorActive ? Math.sin(progress * 90) * 3 * s : 0;
  const problemFadeOut = interpolate(progress, [0.40, 0.48], [1, 0], CLAMP);
  const problemFallY = interpolate(progress, [0.40, 0.50], [0, height * 0.35], CLAMP);

  const solutionOverall = interpolate(progress, [0.50, 0.55], [0, 1], CLAMP);

  const SOLUTION_LAND = [0.55, 0.70] as const;
  const solutionLandP = spring(
    interpolate(progress, [SOLUTION_LAND[0], SOLUTION_LAND[1]], [0, 1], CLAMP),
    { damping: 9, stiffness: 220 },
  );
  const solutionLandScale = interpolate(solutionLandP, [0, 1], [0.7, 1]);
  const solutionLandRiseY = interpolate(solutionLandP, [0, 1], [40 * s, 0]);
  const solutionLandOpacity = interpolate(
    progress,
    [SOLUTION_LAND[0], SOLUTION_LAND[0] + 0.05],
    [0, 1],
    CLAMP,
  );
  const solutionLabelOpacity = solutionLandOpacity;
  const solutionPillScale = solutionLandScale;
  const solutionTextOpacity = solutionLandOpacity;
  const solutionTextScale = solutionLandScale;
  const solutionTextRiseY = solutionLandRiseY;

  // Confetti burst — fires UPWARD from above the pill as it lands.
  const CONFETTI_COUNT = 14;
  const CONFETTI_ANGLE_JITTER = [-12, 8, -5, 14, -7, 11, -16, 6, -9, 13, -4, 10, -11, 7];
  const CONFETTI_DISTANCE = [60, 230, 100, 180, 130, 260, 80, 210, 50, 240, 150, 90, 220, 170];
  const CONFETTI_ROTATION = [-180, 220, -140, 260, -200, 180, -240, 200, -160, 240, -200, 280, -180, 220];
  const CONFETTI_COLORS = [
    "#22c55e",
    "#4ade80",
    "#86efac",
    "#bbf7d0",
    "#dcfce7",
    "#f0fdf4",
  ];
  const CONFETTI_TINT_INDEX = [0, 1, 2, 0, 3, 1, 4, 0, 2, 1, 5, 0, 3, 2];
  const confettiRaw = interpolate(progress, [0.55, 0.70], [0, 1], CLAMP);
  const confettiActive = confettiRaw > 0 && confettiRaw < 1;
  const confettiDist = 1 - Math.pow(1 - confettiRaw, 2.5);

  return (
    <>
      {/* Problem phase — falls down on exit */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: problemFadeOut,
          transform: `translateY(${problemFallY}px)`,
        }}
      >
        {/* Pill */}
        <div
          style={{
            position: "absolute",
            top: pillTop,
            left: 0,
            right: 0,
            display: "flex",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              fontSize: labelFontSize,
              fontWeight: 700,
              color: problemColor,
              letterSpacing: 3 * s,
              textTransform: "uppercase" as const,
              whiteSpace: "nowrap" as const,
              opacity: problemLabelOpacity,
              transform: `scale(${problemPillScale})`,
              transformOrigin: "center center",
              fontFamily: font,
              backgroundColor: "rgba(0,0,0,0.3)",
              border: "1px solid rgba(255,255,255,0.15)",
              borderRadius: 100 * s,
              padding: `${14 * s}px ${36 * s}px`,
              textShadow: "0 1px 6px rgba(0,0,0,0.1)",
            }}
          >
            {problemLabel}
          </div>
        </div>
        {/* Main text */}
        <div
          style={{
            position: "absolute",
            top: textTop,
            left: 0,
            right: 0,
            fontSize: mainSize,
            fontWeight: 800,
            color: textColor,
            textAlign: "center" as const,
            padding: `0 ${60 * s}px`,
            lineHeight: 1.2,
            letterSpacing: -1,
            opacity: problemTextOpacity,
            transform: `translateX(${tremorX}px) scale(${problemTextScale})`,
            fontFamily: font,
            textShadow: "0 2px 12px rgba(0,0,0,0.15)",
          }}
        >
          {problemText}
        </div>
      </div>

      {/* Solution phase */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: solutionOverall,
        }}
      >
        {/* Confetti burst */}
        {confettiActive && Array.from({ length: CONFETTI_COUNT }, (_, i) => {
          const baseAngle = 200 + (i / (CONFETTI_COUNT - 1)) * 140 + CONFETTI_ANGLE_JITTER[i];
          const angleRad = baseAngle * Math.PI / 180;
          const distance = confettiDist * CONFETTI_DISTANCE[i] * s;
          const gravity = confettiRaw * confettiRaw * 35 * s;
          const dx = Math.cos(angleRad) * distance;
          const dy = Math.sin(angleRad) * distance + gravity;
          const rot = confettiRaw * CONFETTI_ROTATION[i];
          const op = interpolate(confettiRaw, [0, 0.08, 0.7, 1], [0, 1, 1, 0]);
          const particleSize = 9 * s;
          const originX = width / 2;
          const originY = pillTop - 6 * s;
          const tint = CONFETTI_COLORS[CONFETTI_TINT_INDEX[i]];
          return (
            <div
              key={`confetti-${i}`}
              style={{
                position: "absolute",
                left: originX - particleSize / 2,
                top: originY - particleSize / 2 * 1.6,
                width: particleSize,
                height: particleSize * 1.6,
                backgroundColor: tint,
                borderRadius: 1 * s,
                transform: `translate(${dx}px, ${dy}px) rotate(${rot}deg)`,
                opacity: op,
                pointerEvents: "none",
                boxShadow: `0 0 ${4 * s}px ${tint}66`,
              }}
            />
          );
        })}

        {/* Pill */}
        <div
          style={{
            position: "absolute",
            top: pillTop,
            left: 0,
            right: 0,
            display: "flex",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              fontSize: labelFontSize,
              fontWeight: 700,
              color: solutionColor,
              letterSpacing: 3 * s,
              textTransform: "uppercase" as const,
              whiteSpace: "nowrap" as const,
              opacity: solutionLabelOpacity,
              transform: `scale(${solutionPillScale})`,
              transformOrigin: "center center",
              fontFamily: font,
              backgroundColor: "rgba(0,0,0,0.3)",
              border: "1px solid rgba(255,255,255,0.15)",
              borderRadius: 100 * s,
              padding: `${14 * s}px ${36 * s}px`,
              textShadow: "0 1px 6px rgba(0,0,0,0.1)",
            }}
          >
            {solutionLabel}
          </div>
        </div>
        {/* Main text */}
        <div
          style={{
            position: "absolute",
            top: textTop,
            left: 0,
            right: 0,
            fontSize: mainSize,
            fontWeight: 800,
            color: textColor,
            textAlign: "center" as const,
            padding: `0 ${60 * s}px`,
            lineHeight: 1.2,
            letterSpacing: -1,
            opacity: solutionTextOpacity,
            transform: `translateY(${solutionTextRiseY}px) scale(${solutionTextScale})`,
            fontFamily: font,
            textShadow: "0 2px 12px rgba(0,0,0,0.15)",
          }}
        >
          {solutionText}
        </div>
      </div>
    </>
  );
};

/**
 * TemplateText — unified text component for scene templates.
 *
 * Replaces the per-template hand-rolled text rendering with a single component
 * that owns: archetype motion lifecycle (entrance + hold + exit), font sizing,
 * position, beat pulse, and safe zone.
 *
 * Each template declares its constraints (position + sizeRole) at the call site;
 * the user/AI picks the archetype. Templates that can only show text at the top
 * just always pass position="top".
 *
 * Example — a data template (caption above a chart):
 *
 *   <TemplateText
 *     archetype={textArchetype}
 *     text={variables.title}
 *     progress={progress}
 *     sceneDuration={sceneDuration}
 *     width={width}
 *     height={height}
 *     position="top"
 *     sizeRole="caption"
 *   />
 *
 * Example — a media template (full-frame headline):
 *
 *   <TemplateText
 *     archetype={textArchetype}
 *     text={variables.headline}
 *     progress={progress}
 *     sceneDuration={sceneDuration}
 *     width={width}
 *     height={height}
 *     position="center"
 *     sizeRole="headline"
 *     beatIntensity={beatIntensity}
 *   />
 *
 * Note: `textArchetype` is destructured from props (a scene-level
 * field on `SceneTemplateProps`), NOT read from `variables`. Copying
 * the wrong pattern silently no-ops — the executor routes
 * `setSceneVariable("textArchetype", ...)` to the scene-level field,
 * never into variables, so `variables.textArchetype` is always
 * undefined.
 */

import {
  renderArchetype,
  normalizeArchetype,
  type TextArchetype,
  type ArchetypeRender,
} from "./text-archetypes";
import { renderWithEmoji, planTypewriterEmoji } from "../emoji/emoji-text";
import { Emoji } from "../emoji";

export type TextPosition = "top" | "center" | "bottom";
export type TextSizeRole = "headline" | "caption" | "label";

export interface SafeZone {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

export interface TemplateTextProps {
  archetype: TextArchetype;
  text: string;
  /** Scene progress 0→1. */
  progress: number;
  /** Scene duration in seconds — drives entrance/exit phase scaling. */
  sceneDuration: number;
  /** Frame width in pixels (1080 in production, smaller in previews). */
  width: number;
  /** Frame height in pixels (1920 in production). */
  height: number;
  /** Where the text box sits in the frame. Templates declare this. */
  position?: TextPosition;
  /** Size envelope. Templates declare this. */
  sizeRole?: TextSizeRole;
  /** Preset type treatment — weight/tracking/size/case shift from style.preset. */
  typeTreatment?: { weightDelta: number; trackingDeltaEm: number; sizeScale: number; transform?: "uppercase" };
  /** Padding from frame edges. Defaults to a 24px box. */
  safeZone?: SafeZone;
  /** Font family. */
  font?: string;
  /** Fill color. */
  color?: string;
  /** Beat intensity 0→1 (currently unused — kept for forward compat). */
  beatIntensity?: number;
}

const DEFAULT_SAFE_ZONE: SafeZone = { top: 24, right: 24, bottom: 24, left: 24 };
const DEFAULT_FONT =
  "ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";

// ─── Typography constants ───────────────────────────────────────
// All em-based so they scale with font size and behave consistently across
// font families. Values from print/motion-design conventions:
//
//  - Big text (display/headline) gets TIGHTER tracking and TIGHTER leading.
//    -0.022em (≈ -2.2%) is the sweet spot for 48–88px headlines on most
//    sans-serifs (Inter, Helvetica, SF Pro, Manrope, Geist).
//  - Word-spacing kept subtle (≤0.08em). CSS word-spacing is ADDITIVE on
//    top of the natural space char, so what looks like "a touch of
//    rhythm" in print becomes a visible double-gap on 80px motion
//    headlines (especially under wordStagger, where each word renders
//    as an inline-block and the gap between them is preserved). Old
//    values (0.16/0.18/0.22 em) added ~13–18px per gap on display
//    type — the "too much space between words" symptom.
//  - Line-height 1.1 for headlines, 1.5 for body — Bringhurst-aligned ratios.
//  - kern + liga always on so any font's pair-kerning and ligatures fire
//    consistently (works across Inter, Manrope, SF, IBM Plex, etc.).
const TYPO = {
  headline: {
    letterSpacing: "-0.022em",
    wordSpacing: "0.04em",
    lineHeight: 1.1,
  },
  caption: {
    letterSpacing: "-0.012em",
    wordSpacing: "0.06em",
    lineHeight: 1.25,
  },
  label: {
    letterSpacing: "-0.005em",
    wordSpacing: "0.10em",
    lineHeight: 1.4,
  },
};
const FONT_FEATURES = '"kern" 1, "liga" 1';

// Drop shadow tuned to give crisp edges on retina without muddying text on
// saturated gradients. Earlier two-layer shadow (1px tight + 16px wide) cast
// dark halos that made gradient-backed text look smudged. A single barely-
// there shadow is enough for edge definition; bg-media adds its own dark
// scrim for legibility over photos, so we don't need to compensate here.
function dropShadowFor(textColor: string): string {
  const dark = isLikelyDark(textColor);
  const tone = dark ? "rgba(255,255,255,0.15)" : "rgba(0,0,0,0.2)";
  return `0 1px 2px ${tone}`;
}

function isLikelyDark(color: string): boolean {
  // Crude luminance check — handles #rrggbb and #rgb. Anything we can't parse
  // (named colors, rgb()) defaults to "not dark" so the heavier shadow shows.
  const m = color.replace("#", "");
  if (m.length === 3) {
    const r = parseInt(m[0] + m[0], 16);
    const g = parseInt(m[1] + m[1], 16);
    const b = parseInt(m[2] + m[2], 16);
    return (r * 299 + g * 587 + b * 114) / 1000 < 128;
  }
  if (m.length === 6) {
    const r = parseInt(m.slice(0, 2), 16);
    const g = parseInt(m.slice(2, 4), 16);
    const b = parseInt(m.slice(4, 6), 16);
    return (r * 299 + g * 587 + b * 114) / 1000 < 128;
  }
  return false;
}
// ─── Font sizing matrix ─────────────────────────────────────────
// Mirrors what production templates actually render today, ported from:
//   - text-overlay.tsx (headline: 80/64/48 × s_min by char count)
//   - infographic-steps.tsx (caption: ~44 × s_min capped by layout)

/**
 * Compute heroWord font size for a single word. Each active word fills its
 * own moment — trailer convention. Center can go large (480ref cap); top
 * stays inside the top zone height so it doesn't crash into the animation
 * or data viz below.
 */
function computeHeroFontSize(
  wordChars: number,
  position: TextPosition,
  width: number,
  height: number,
  safeZone: SafeZone,
): number {
  const chars = Math.max(wordChars, 1);
  const s_min = Math.min(width, height) / 1080;
  const widthBudget = (width - safeZone.left - safeZone.right) * 0.92;
  const pxPerChar = 0.58; // bold sans-serif approximation
  const widthCap = widthBudget / (chars * pxPerChar);

  if (position === "center") {
    return Math.min(480 * s_min, widthCap);
  }

  // Top/bottom: keep the word inside its zone (~28% of frame height) with
  // 80% headroom for entrance overshoot + breathe. Reference target 220ref
  // so even short words stay big without overflowing the zone.
  const heightCap = height * 0.28 * 0.8;
  return Math.min(220 * s_min, widthCap, heightCap);
}

/**
 * Smooth interpolation between max and min font size based on character count.
 * Avoids the visible "jump" you get from bucket boundaries when copy length
 * crosses a threshold (e.g., 25→26 chars dropping headline from 80px to 64px).
 *
 * Exported so templates that lay out their own text can match the headline
 * curve instead of inventing their own bucketed scaling.
 *
 * Returns size at 1080-reference scale; caller multiplies by s_min.
 */
export function smoothSize(chars: number, maxChars: number, max: number, min: number): number {
  const t = Math.max(0, Math.min(1, chars / maxChars));
  // Slight curve so short text stays at maxSize longer before scaling down.
  const eased = t * t;
  return max - (max - min) * eased;
}

function computeFontSize(
  archetype: TextArchetype,
  text: string,
  role: TextSizeRole,
  position: TextPosition,
  width: number,
  height: number,
  safeZone: SafeZone,
): { fontSize: number; fontWeight: number } {
  const s_min = Math.min(width, height) / 1080;

  // heroWord container fontSize uses the longest word as a safe fallback. The
  // ACTIVE-word size is recomputed per-render in the "hero" render branch
  // (via computeHeroFontSize) so each word fills its own moment optimally —
  // trailer convention.
  if (archetype === "heroWord") {
    const longestChars = text
      .split(/\s+/)
      .filter(Boolean)
      .reduce((m, w) => Math.max(m, w.length), 1);
    return {
      fontSize: computeHeroFontSize(longestChars, position, width, height, safeZone),
      fontWeight: 800,
    };
  }

  const chars = text.length;

  // Smooth scaling, minimums set so even long copy stays readable in production
  // (1080 reference). Numbers tuned to match — but improve on — the previous
  // bucketed system.
  if (role === "headline") {
    // Floor 60 (was 48) — matches the typography guideline "Titles/headlines
    // 60-86px at 1080" and lifts long-copy headlines off the body-text floor
    // that left ProblemSolution-shaped statements feeling small. Max held at
    // 88 so short, punchy headlines still fill the frame.
    const refSize = smoothSize(chars, /* maxChars */ 70, /* max */ 88, /* min */ 60);
    return { fontSize: refSize * s_min, fontWeight: 700 };
  }

  if (role === "caption") {
    const refSize = smoothSize(chars, 80, 48, 32);
    return { fontSize: refSize * s_min, fontWeight: 600 };
  }

  // label
  const refSize = smoothSize(chars, 80, 34, 24);
  return { fontSize: refSize * s_min, fontWeight: 500 };
}

// ─── Positioning ───────────────────────────────────────────────

function positionStyle(
  position: TextPosition,
  height: number,
  safeZone: SafeZone,
): React.CSSProperties {
  switch (position) {
    case "top":
      return {
        top: safeZone.top + height * 0.06,
        height: height * 0.28,
        alignItems: "flex-start",
      };
    case "bottom":
      return {
        bottom: safeZone.bottom + height * 0.06,
        height: height * 0.28,
        alignItems: "flex-end",
      };
    case "center":
    default:
      return {
        top: 0,
        bottom: 0,
        alignItems: "center",
      };
  }
}

// ─── Component ─────────────────────────────────────────────────

export const TemplateText: React.FC<TemplateTextProps> = ({
  archetype: archetypeRaw,
  text: textRaw,
  progress,
  sceneDuration,
  width,
  height,
  position = "center",
  sizeRole = "headline",
  typeTreatment,
  safeZone = DEFAULT_SAFE_ZONE,
  font = DEFAULT_FONT,
  color = "#FFFFFF",
  beatIntensity = 0,
}) => {
  // Defensive coerce: TemplateText is downstream of ~16 templates that pass
  // their own `variables.X` strings. If any one of them passes undefined
  // (missing variable on a freshly added scene, stale saved config, vibecoded
  // template not setting a field), the unguarded `.split` / `.length` calls
  // below crash the entire Studio preview. Treat undefined/non-string as
  // empty so a single bad scene doesn't take everything down. Warn in dev
  // so the upstream gap still surfaces.
  const textSafe = typeof textRaw === "string" ? textRaw : "";
  if (textRaw !== undefined && typeof textRaw !== "string" && import.meta.env.DEV) {
    console.warn("[TemplateText] received non-string text:", textRaw);
  }
  // `|` is the AI's explicit line-break convention for headline copy
  // ("Built for speed.|Designed for you."). Convert centrally so EVERY
  // template that renders text through TemplateText honors it — bg-media
  // used to convert locally while confetti/emojiBurst/etc. rendered the
  // pipe literally. Whitespace around the pipe is trimmed so spaced and
  // unspaced pipes produce identical output. The container's
  // `white-space: pre-line` renders the resulting `\n` as a hard break.
  // Templates that legitimately render pipes (code, terminal commands)
  // don't flow through TemplateText, so they're unaffected.
  const text = textSafe.replace(/\s*\|\s*/g, "\n");
  // Normalize the archetype prop so legacy effect names from old saved
  // configs (e.g., "fade-in") map to a real archetype instead of crashing.
  const archetype = normalizeArchetype(archetypeRaw);
  const scale = Math.min(width, height) / 1080;
  const result: ArchetypeRender = renderArchetype(archetype, progress, scale, text, sceneDuration);
  const { fontSize, fontWeight } = computeFontSize(
    archetype,
    text,
    sizeRole,
    position,
    width,
    height,
    safeZone,
  );

  // beatIntensity reserved for future use; currently a no-op on text body.
  void beatIntensity;

  const baseTypo = TYPO[sizeRole];
  // Preset type treatment. Absent (or the default preset's zero-deltas) leaves
  // every value exactly as it was, so unpresetted configs are unaffected.
  const tt = sizeRole === "headline" ? typeTreatment : undefined;
  // Only rewrite a value the preset actually changes — reformatting
  // letterSpacing with a zero delta would alter the emitted string (and every
  // stability snapshot) without changing the render.
  const typo = tt
    ? {
        ...baseTypo,
        ...(tt.trackingDeltaEm !== 0
          ? {
              letterSpacing: `${Number(
                (parseFloat(baseTypo.letterSpacing) + tt.trackingDeltaEm).toFixed(4),
              )}em`,
            }
          : {}),
        ...(tt.transform ? { textTransform: tt.transform } : {}),
      }
    : baseTypo;
  const presetWeight = tt ? Math.min(900, Math.max(100, fontWeight + tt.weightDelta)) : fontWeight;
  const presetSize = tt ? fontSize * tt.sizeScale : fontSize;
  const textShadow = dropShadowFor(color);

  const containerStyle: React.CSSProperties = {
    position: "absolute",
    left: 0,
    right: 0,
    display: "flex",
    justifyContent: "center",
    padding: `0 ${safeZone.right}px 0 ${safeZone.left}px`,
    color,
    fontFamily: font,
    fontWeight: presetWeight,
    fontSize: presetSize,
    textAlign: "center",
    pointerEvents: "none",
    fontFeatureSettings: FONT_FEATURES,
    textRendering: "optimizeLegibility",
    WebkitFontSmoothing: "antialiased",
    MozOsxFontSmoothing: "grayscale",
    // Respect explicit newlines — the centralized `|` → `\n` conversion
    // above (and callers passing real newlines) rely on this. Multiple
    // spaces still collapse normally; only `\n` and CRLF break.
    whiteSpace: "pre-line",
    ...(textShadow ? { textShadow } : {}),
    ...typo,
    ...positionStyle(position, height, safeZone),
  };

  if (result.kind === "block") {
    return (
      <div style={containerStyle}>
        <div
          style={{
            opacity: result.block.opacity,
            transform: `${result.block.transform}`,
            // Inherit letter-spacing from the container's typography defaults
            // unless the archetype explicitly overrides (e.g., for animated tracking).
            ...(result.block.letterSpacing ? { letterSpacing: result.block.letterSpacing } : {}),
            ...(result.block.willChange ? { willChange: result.block.willChange } : {}),
            maxWidth: "85%",
          }}
        >
          {renderWithEmoji(result.text, fontSize)}
        </div>
      </div>
    );
  }

  if (result.kind === "typewriter") {
    // Render every character as its own span so the FULL TEXT always sets the
    // layout — wrapping is decided by the complete string, not the typed
    // prefix. The cursor is overlaid with position:absolute from the last
    // typed char so it doesn't break the word it's inside.
    const chars = text.split("");
    // Map cluster-start code-unit indices → mapped emoji-PNG image so color
    // emoji render as images even in the per-char typewriter reveal. Indexing
    // stays on text.length (UTF-16 units) so result.visibleChars / charExits
    // line up exactly; continuation units of a cluster render nothing.
    const emojiPlan = planTypewriterEmoji(text);
    const cursorBar = {
      position: "absolute" as const,
      width: "0.08em",
      height: "0.88em",
      background: "currentColor",
      borderRadius: "0.01em",
      pointerEvents: "none" as const,
    };
    return (
      <div style={containerStyle}>
        <div
          style={{
            opacity: result.opacity,
            maxWidth: "85%",
            whiteSpace: "pre-wrap",
            position: "relative",
          }}
        >
          {chars.map((ch, i) => {
            const isTyped = i < result.visibleChars;
            const isLastTyped = i === result.visibleChars - 1;
            const anchorCursor = isLastTyped && result.cursor;
            const charExit = result.charExits?.[i];
            const baseOpacity = isTyped ? 1 : 0;
            const finalOpacity = baseOpacity * (charExit?.opacity ?? 1);
            // During exit the per-char span needs inline-block so translateX
            // takes effect; whiteSpace: pre keeps space chars from collapsing.
            const exitStyle = charExit
              ? {
                  display: "inline-block" as const,
                  transform: `translateX(${charExit.translateX}px)`,
                  whiteSpace: "pre" as const,
                }
              : null;
            // Emoji handling: a cluster-start unit renders the mapped PNG; the
            // cluster's continuation units render nothing (image spans them).
            const emojiChar = emojiPlan?.starts.get(i);
            if (emojiPlan?.covered.has(i)) return null;
            return (
              <span
                key={i}
                style={{
                  opacity: finalOpacity,
                  position: anchorCursor ? "relative" : "static",
                  ...(exitStyle ?? {}),
                }}
              >
                {emojiChar ? <Emoji char={emojiChar} size={fontSize} /> : ch}
                {anchorCursor && (
                  <span
                    aria-hidden
                    style={{
                      ...cursorBar,
                      left: "100%",
                      top: "0.08em",
                      marginLeft: "0.12em",
                    }}
                  />
                )}
              </span>
            );
          })}
          {result.visibleChars === 0 && result.cursor && (
            <span
              aria-hidden
              style={{
                ...cursorBar,
                left: 0,
                top: "0.08em",
              }}
            />
          )}
        </div>
      </div>
    );
  }

  if (result.kind === "words") {
    // Render words inline-block with REAL space chars between them — word
    // spacing inherits from the container's typography defaults, matching
    // every other archetype's wrap behavior.
    return (
      <div style={containerStyle}>
        <div
          style={{
            opacity: result.blockOpacity,
            transform: `${result.blockTransform} `,
            maxWidth: "85%",
          }}
        >
          {result.words.map((w, i) => (
            <span key={i}>
              <span
                style={{
                  display: "inline-block",
                  opacity: w.style.opacity,
                  transform: w.style.transform,
                }}
              >
                {renderWithEmoji(w.text, fontSize)}
              </span>
              {i < result.words.length - 1 ? " " : ""}
            </span>
          ))}
        </div>
      </div>
    );
  }

  if (result.kind === "hero") {
    // Per-word sizing: each active word fills its own moment optimally.
    const perWordFontSize = computeHeroFontSize(
      result.word.length,
      position,
      width,
      height,
      safeZone,
    );
    // Fixed-height slot so words of different sizes don't jump vertically.
    // Slot is the max possible hero size for this position; lineHeight: 1 on
    // the inner word locks the glyph box to the font height so flex-center
    // lands the glyph at the same Y for every word.
    const slotHeight =
      position === "center" ? 480 * scale : Math.min(220 * scale, height * 0.28 * 0.8);
    return (
      <div style={{ ...containerStyle, fontSize: perWordFontSize }}>
        <div
          style={{
            height: slotHeight,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              opacity: result.opacity,
              transform: `${result.transform} `,
              lineHeight: 1,
              ...(result.letterSpacing ? { letterSpacing: result.letterSpacing } : {}),
            }}
          >
            {renderWithEmoji(result.word, perWordFontSize)}
          </div>
        </div>
      </div>
    );
  }

  return null;
};

/**
 * Emoji — render emojis as inline PNG data-URI <img> elements.
 *
 * Why images, not the system emoji font: VanillaSky renders the same scene
 * three ways — real-DOM preview, client SVG-as-image export, server Puppeteer.
 * Raw-unicode emojis fall through to whatever emoji font the OS has (Mac=Apple,
 * Linux=Noto), so preview and export disagree. Inlining each emoji as a
 * data-URI <img> renders the SAME PNG in all three. Critically, the
 * client export rasterizes the frame via <img src="data:image/svg+xml">, which
 * can ONLY load inlined data-URI images (not @font-face, not external URLs) —
 * so data URIs are exactly what works there.
 *
 * Source artwork: emoji-datasource-google (Google Noto emoji set, Apache-2.0).
 * The map ships inside the publicly redistributed skill tarball, and Apple's
 * artwork is not licensed for redistribution — Noto's Apache-2.0 is. The set
 * is swappable via the generator's EMOJI_SET constant
 * (scripts/generate-emoji-map.mjs).
 *
 * Bundle: the generated char→dataURI map is ~1.1MB of base64, so it is
 * LAZY-LOADED via dynamic import and never enters the initial app bundle. The
 * import is kicked off eagerly at module load (below) — long before any export
 * or screenshot — so by the time a frame is captured the map has resolved.
 * Until it resolves, <Emoji> renders the raw unicode char, then re-renders to
 * the image when the map lands. Any emoji not in the map also falls back to the
 * raw char, so nothing ever breaks for custom/unmapped emojis.
 */

import * as React from "react";

let EMOJI_MAP: Record<string, string> | null = null;
let loadPromise: Promise<Record<string, string>> | null = null;
const subscribers = new Set<() => void>();

function loadEmojiMap(): Promise<Record<string, string>> {
  if (loadPromise) return loadPromise;
  loadPromise = import("./emoji-map.generated")
    .then((mod) => {
      EMOJI_MAP = mod.default;
      subscribers.forEach((fn) => fn());
      return EMOJI_MAP;
    })
    .catch((err) => {
      // Network/chunk failure: leave map null → everything falls back to char.
      console.warn("[emoji] failed to load emoji map:", err);
      EMOJI_MAP = {};
      return EMOJI_MAP;
    });
  return loadPromise;
}

// Kick off the load immediately when this module is first imported (app/registry
// init), so the map is ready well before any export or server screenshot.
loadEmojiMap();

/**
 * Resolve once the emoji-PNG map has loaded (or definitively failed). Render
 * paths that capture frames MUST await this before their first capture so they
 * never screenshot a frame while emoji are still raw-unicode chars:
 *   - server: Render.tsx awaits before setting window.__ready
 *   - client export: export-video.ts awaits in the media-preload step
 * The preview path doesn't capture, so it can stay lazy (subscribers re-render
 * char → image when the map lands). On chunk failure this resolves to {} so
 * the await never hangs — everything falls back to the raw char.
 */
export function ensureEmojiMap(): Promise<Record<string, string>> {
  return loadEmojiMap();
}

/**
 * Returns the emoji-PNG data URI for an emoji char, or null if the map hasn't
 * loaded yet or the char isn't in the set (caller should fall back to the char).
 */
export function emojiToDataUri(char: string): string | null {
  if (!EMOJI_MAP) return null;
  const key = (char || "").trim();
  if (EMOJI_MAP[key]) return EMOJI_MAP[key];
  // Tolerate a trailing variation selector mismatch (U+FE0F).
  const stripped = key.replace(/️/g, "");
  if (stripped !== key && EMOJI_MAP[stripped]) return EMOJI_MAP[stripped];
  return null;
}

/** Subscribe to map-loaded so a component re-renders char → image when ready. */
function useEmojiMapReady(): boolean {
  const [, force] = React.useReducer((n: number) => n + 1, 0);
  React.useEffect(() => {
    if (EMOJI_MAP) return;
    const fn = () => force();
    subscribers.add(fn);
    loadEmojiMap();
    return () => {
      subscribers.delete(fn);
    };
  }, []);
  return EMOJI_MAP != null;
}

export interface EmojiProps {
  /** The emoji character(s), e.g. "🎉". */
  char: string;
  /** Box size in px — matches the prior glyph's font-size so layout is identical. */
  size: number;
  /** vertical-align for inline flow. Defaults to a glyph-like baseline nudge. */
  verticalAlign?: React.CSSProperties["verticalAlign"];
  /** Extra styles merged onto the <img> (or fallback <span>). */
  style?: React.CSSProperties;
}

/**
 * Renders an emoji as an inline emoji-PNG <img> when available, else the raw
 * unicode char in a same-size box (so scale/opacity/transform are unchanged).
 */
export const Emoji: React.FC<EmojiProps> = ({ char, size, verticalAlign = "-0.15em", style }) => {
  useEmojiMapReady();
  const uri = emojiToDataUri(char);

  if (!uri) {
    // Fallback: raw char sized to the same box so layout/scale are preserved.
    return (
      <span
        style={{
          fontSize: size,
          lineHeight: 1,
          display: "inline-block",
          ...style,
        }}
      >
        {char}
      </span>
    );
  }

  return (
    <img
      src={uri}
      alt={char}
      width={size}
      height={size}
      style={{
        width: size,
        height: size,
        objectFit: "contain",
        display: "inline-block",
        verticalAlign,
        ...style,
      }}
    />
  );
};

/**
 * EmojiText / renderWithEmoji — split a string into text runs + color-emoji
 * runs, rendering each color emoji as an inline emoji-PNG <img> (via <Emoji>)
 * while leaving everything else as plain text.
 *
 * Why this exists: raw-unicode emoji fall through to the OS emoji font (Mac =
 * Apple, Linux = Noto), so the three render paths (preview / client SVG export
 * / server Puppeteer) disagree. Wrapping every template/AI-supplied string here
 * makes ALL color emoji render as the same mapped PNG in all three.
 *
 * What it does NOT touch: monochrome symbols (★ ✦ ✓ → ↑ …). Those render
 * identically as text across OSes, and imaging them would be wrong. The gate
 * is `emojiToDataUri()` — only clusters that resolve to a PNG in the
 * map become <img>; anything else (monochrome symbols, unmapped/custom
 * emoji, skin-tone variants not in the set) stays raw text.
 *
 * Segmentation: grapheme clusters via Intl.Segmenter so ZWJ sequences
 * (👩‍💻) and skin-tone modifiers (👍🏽) stay single units. Adjacent emoji
 * clusters each render as their own <img> in sequence.
 *
 * Sizing: each emoji <img> is sized to `fontSizePx` (the surrounding font
 * size) so the emoji box matches a glyph box — width/line-count stay
 * ~identical to the raw-text layout, which keeps fitTextSize / archetype
 * char-count measurement valid (all string-based, never DOM-measured).
 */

import * as React from "react";
import { Emoji, emojiToDataUri } from "./index";

// Coarse "is this cluster a color-emoji candidate?" test. Deliberately broad:
// the real decision is whether emojiToDataUri() resolves it to a mapped PNG.
// This regex only needs to (a) catch the OS-divergent color ranges and (b)
// avoid flagging plain text/whitespace so we don't merge text into emoji runs.
//
//  - \u{1F000}-\u{1FAFF}  — main emoji planes (most pictographs)
//  - \u{2600}-\u{27BF}    — misc symbols + dingbats (color when + FE0F)
//  - \u{2B00}-\u{2BFF}    — stars/arrows block (⭐ lives here)
//  - \u{1F1E6}-\u{1F1FF}  — regional indicators (flags)
//  - \u{1F3FB}-\u{1F3FF}  — skin-tone modifiers
//  - \u{FE0F} | \u{200D} | \u{20E3} — VS16 / ZWJ / keycap combiners
//
// Combining/joiner codepoints (FE0F, ZWJ, keycap) are matched via alternation
// rather than inside the character class — eslint's
// no-misleading-character-class flags combining chars inside `[...]`, and
// alternation is equivalent here (we only test, never capture).
const EMOJI_CANDIDATE =
  /[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{1F1E6}-\u{1F1FF}]|[\u{1F3FB}-\u{1F3FF}]|\u{FE0F}|\u{200D}|\u{20E3}/u;

function isEmojiCandidate(cluster: string): boolean {
  return EMOJI_CANDIDATE.test(cluster);
}

/** Split text into grapheme clusters (ZWJ + skin-tone safe). */
function toGraphemes(text: string): string[] {
  const Seg = (Intl as unknown as { Segmenter?: typeof Intl.Segmenter }).Segmenter;
  if (Seg) {
    const seg = new Seg(undefined, { granularity: "grapheme" });
    const out: string[] = [];
    for (const { segment } of seg.segment(text)) out.push(segment);
    return out;
  }
  // Fallback: code-point spread. Won't keep ZWJ/skin-tone as single units, so
  // those land as separate clusters; emojiToDataUri's FE0F tolerance + the raw
  // fallback keep them from breaking. Modern browsers all have Segmenter.
  return Array.from(text);
}

export interface RenderWithEmojiOptions {
  /** vertical-align passed to each <Emoji>. */
  verticalAlign?: React.CSSProperties["verticalAlign"];
  /** Extra style merged onto each emoji <img>. */
  emojiStyle?: React.CSSProperties;
}

/**
 * Split `text` into an array of React nodes — plain-text strings interleaved
 * with <Emoji> images for every mapped color emoji. Returns a single-element
 * `[text]` fast-path when there are no color emoji (the common case), so
 * non-emoji text pays ~one regex test.
 *
 * @param text         the string to render
 * @param fontSizePx   surrounding font size in px (emoji box = this size)
 */
export function renderWithEmoji(
  text: string,
  fontSizePx: number,
  opts?: RenderWithEmojiOptions,
): React.ReactNode[] {
  if (!text) return [text];
  // Cheap bail-out: if the whole string has no emoji-range codepoint, return
  // it untouched (no segmentation, no array churn) — the hot path for the vast
  // majority of titles/bodies.
  if (!EMOJI_CANDIDATE.test(text)) return [text];

  const clusters = toGraphemes(text);
  const nodes: React.ReactNode[] = [];
  let textBuf = "";
  let key = 0;

  const flushText = () => {
    if (textBuf) {
      nodes.push(textBuf);
      textBuf = "";
    }
  };

  for (const cluster of clusters) {
    const uri = isEmojiCandidate(cluster) ? emojiToDataUri(cluster) : null;
    if (uri) {
      flushText();
      nodes.push(
        <Emoji
          key={`e${key++}`}
          char={cluster}
          size={fontSizePx}
          verticalAlign={opts?.verticalAlign}
          style={opts?.emojiStyle}
        />,
      );
    } else {
      textBuf += cluster;
    }
  }
  flushText();
  return nodes;
}

/**
 * Per-code-unit emoji plan for the typewriter archetype, which reveals text
 * one UTF-16 code unit at a time and indexes by `text.length`. We can't just
 * call renderWithEmoji there (it would re-segment and desync the visibleChars
 * counter), so this maps each cluster's START code-unit index to its emoji-PNG
 * data URI and marks the cluster's CONTINUATION indices as covered (render
 * nothing for them — the start index's <img> already spans the whole cluster).
 *
 * Returns null when the text contains no mapped color emoji (the common case),
 * so the typewriter render keeps its plain per-char path.
 */
export interface EmojiTypewriterPlan {
  /** code-unit index → full emoji cluster char (cluster start). */
  starts: Map<number, string>;
  /** code-unit indices that are continuations of a cluster (render nothing). */
  covered: Set<number>;
}

export function planTypewriterEmoji(text: string): EmojiTypewriterPlan | null {
  if (!text || !EMOJI_CANDIDATE.test(text)) return null;
  const starts = new Map<number, string>();
  const covered = new Set<number>();
  let idx = 0;
  let found = false;
  for (const cluster of toGraphemes(text)) {
    const len = cluster.length; // UTF-16 code units
    if (isEmojiCandidate(cluster) && emojiToDataUri(cluster)) {
      found = true;
      // Store the WHOLE cluster char (not just the start unit) so callers can
      // pass it straight to <Emoji> for a correct map lookup.
      starts.set(idx, cluster);
      for (let k = 1; k < len; k++) covered.add(idx + k);
    }
    idx += len;
  }
  return found ? { starts, covered } : null;
}

export interface EmojiTextProps {
  /** The text to render, color emoji replaced with emoji-PNG <img>. */
  children: string;
  /** Surrounding font size in px — sizes each emoji image to match a glyph. */
  fontSize: number;
  verticalAlign?: React.CSSProperties["verticalAlign"];
  emojiStyle?: React.CSSProperties;
}

/**
 * Inline wrapper around renderWithEmoji. Renders a React.Fragment of text +
 * emoji <img> runs. Use where a component currently renders a raw `{text}`
 * child and you have the surrounding font size in px.
 */
export const EmojiText: React.FC<EmojiTextProps> = ({
  children,
  fontSize,
  verticalAlign,
  emojiStyle,
}) => {
  const text = typeof children === "string" ? children : "";
  return <>{renderWithEmoji(text, fontSize, { verticalAlign, emojiStyle })}</>;
};

/**
 * Text archetypes — 7 complete lifecycles (entrance + hold + exit).
 *
 * Each archetype is a single named effect that owns its full lifecycle: how
 * text arrives, how it sits, how it leaves. The AI picks one name and that's
 * the whole package.
 *
 * Motion design principles applied per archetype:
 *  - Distinct easing per phase (entrance ≠ exit, archetype-tuned)
 *  - Anticipation / overshoot where the role calls for it
 *  - Hold-phase breathing — no dead frames, ever
 *  - Compound motion — multiple properties (scale, opacity, translate,
 *    letter-spacing) move together with subtle offsets
 *  - Exits are absolute-timed (in seconds), not a fixed % of scene, so
 *    motion stays readable on long scenes too
 *
 * Filter:blur is unavailable (template determinism), so depth illusions are
 * carried by scale magnitude + letter-spacing + opacity ramp shape.
 */

import {
  interpolate,
  spring,
  Easing,
  SPRING_SNAPPY,
  SPRING_SMOOTH,
  SPRING_BOUNCY,
  SPRING_CRISP,
} from "../react-animations/animation-utils";

// ─── Archetype names ────────────────────────────────────────────

export const TEXT_ARCHETYPES = [
  "subtle",
  "typewriter",
  "wordStagger",
  "slam",
  "cinematic",
  "heroWord",
] as const;

export type TextArchetype = (typeof TEXT_ARCHETYPES)[number];
export type TextCanvas = "tight" | "open";
export type TextRole = "hook" | "body" | "closer";

// Maps legacy text-effect names (from saved configs pre-migration) onto the
// new archetype set. Anything not in this map or TEXT_ARCHETYPES falls back
// to `subtle`.
const LEGACY_TO_ARCHETYPE: Record<string, TextArchetype> = {
  "fade-in": "subtle",
  "drift-in": "subtle",
  "slide-up": "subtle",
  "slide-down": "subtle",
  "cut-in": "subtle",
  "zoom-in": "slam",
  "zoom-crisp": "slam",
  "zoom-through": "slam",
  "bounce-drop": "slam",
  typewriter: "typewriter",
  "word-stagger": "wordStagger",
  "word-slam": "wordStagger",
  "word-drop": "wordStagger",
  "oversized-word-reveal": "heroWord",
};

/**
 * Normalize an archetype-ish input to a valid TextArchetype. Handles:
 *  - undefined / null / empty → "subtle"
 *  - already-valid archetype name → unchanged
 *  - legacy effect name (e.g. "fade-in") → mapped equivalent
 *  - unknown string → "subtle" fallback
 */
export function normalizeArchetype(input: unknown): TextArchetype {
  if (typeof input !== "string" || input.length === 0) return "subtle";
  if ((TEXT_ARCHETYPES as readonly string[]).includes(input)) return input as TextArchetype;
  return LEGACY_TO_ARCHETYPE[input] ?? "subtle";
}

// ─── Spec data ──────────────────────────────────────────────────

export interface ArchetypeSpec {
  name: TextArchetype;
  description: string;
  /** Entrance phase duration in seconds. */
  entrance: number;
  /** Exit phase duration in seconds. */
  exit: number;
  /** Where this archetype is allowed to run. */
  allowedCanvas: TextCanvas[];
  /** Suggested role(s) in the video arc. */
  roles: TextRole[];
  /** Font-size multiplier envelope vs. the slot's natural body size. */
  sizeRange: [number, number];
  /**
   * Minimum DURATION the effect itself needs (seconds), with SHORT text.
   * For text-dependent archetypes (typewriter, wordStagger, heroWord) the
   * actual minimum scales with content length — use `minDurationFor()` for
   * an accurate per-text computation.
   */
  minDuration: number;
  /**
   * Maximum DURATION the effect itself uses (seconds). On a longer scene,
   * the effect runs for at most this long, then disappears — leaving the
   * remaining scene time for the AI to fill with another effect. Prevents
   * "ages to build up" on long scenes.
   *
   * If text is so long that `minDurationFor()` exceeds this value, the
   * minimum wins (text needs the time).
   */
  maxDuration: number;
}

// Timings tuned to research findings (Material 3 motion tokens, AE motion-design
// conventions, "exits faster than entrances by 60–75%" rule). Values target
// 2.5s scene by default; phase math scales for longer scenes.
export const ARCHETYPE_SPECS: Record<TextArchetype, ArchetypeSpec> = {
  subtle: {
    name: "subtle",
    description: "Quiet caption. Visual is the star, text supports.",
    entrance: 0.5,
    exit: 0.7,
    allowedCanvas: ["tight", "open"],
    roles: ["body", "closer"],
    sizeRange: [0.7, 1.0],
    minDuration: 1.5,
    maxDuration: 5,
  },
  typewriter: {
    name: "typewriter",
    description: "Char-by-char reveal with blinking cursor. Slide-left cascade exit, top line first.",
    entrance: 1.2,
    exit: 0.85,
    allowedCanvas: ["tight", "open"],
    roles: ["body", "hook"],
    sizeRange: [0.8, 1.0],
    minDuration: 1.8,
    maxDuration: 6,
  },
  wordStagger: {
    name: "wordStagger",
    description: "Sequential word build with active-word focus. Slide-left cascade exit, top line first.",
    entrance: 1.4,
    exit: 0.7,
    allowedCanvas: ["tight", "open"],
    roles: ["body"],
    sizeRange: [0.8, 1.0],
    minDuration: 1.8,
    maxDuration: 6,
  },
  slam: {
    name: "slam",
    description: "In-place impact with violent squash-and-stretch, frame shake, and letter crunch.",
    entrance: 0.5,
    exit: 0.5,
    allowedCanvas: ["tight", "open"],
    roles: ["hook", "body"],
    sizeRange: [0.9, 1.2],
    minDuration: 1.2,
    maxDuration: 4,
  },
  cinematic: {
    name: "cinematic",
    description: "Trailer FlyIn from depth → recedes back into background.",
    entrance: 0.7,
    exit: 0.8,
    allowedCanvas: ["open"],
    roles: ["hook", "body", "closer"],
    sizeRange: [0.9, 1.1],
    minDuration: 1.8,
    maxDuration: 6,
  },
  heroWord: {
    name: "heroWord",
    description: "Single word fills frame. Simple fast exit so words get the most time.",
    entrance: 0.35,
    exit: 0.25,
    allowedCanvas: ["open"],
    roles: ["hook", "body", "closer"],
    sizeRange: [2.0, 3.0],
    minDuration: 1.0,
    maxDuration: 5,
  },
};

// ─── Lifecycle constants ────────────────────────────────────────

const ENTRANCE_START = 0.02;
// Phase caps prevent very short scenes from making in/out exceed the scene.
const ENTRANCE_PHASE_CAP = 0.4;
const EXIT_PHASE_CAP = 0.4;

// ─── Render output shapes ───────────────────────────────────────

export interface BlockStyle {
  opacity: number;
  transform: string;
  letterSpacing?: string;
  /**
   * `willChange` hint to keep the layer GPU-composited during animation.
   * Used by cinematic where the scale-collapse needs to stay smooth on
   * mobile Safari (which otherwise downgrades the layer mid-animation).
   */
  willChange?: string;
}

export interface PerWordStyle {
  text: string;
  style: BlockStyle;
}

export type ArchetypeRender =
  | { kind: "block"; block: BlockStyle; text: string }
  | {
      kind: "typewriter";
      visibleChars: number;
      cursor: boolean;
      opacity: number;
      transform: string;
      /**
       * Per-character exit overrides — present during the exit phase to
       * drive a slide-left cascade in reading order. One entry per char
       * in `text`. Undefined during entrance/hold.
       */
      charExits?: { opacity: number; translateX: number }[];
    }
  | {
      kind: "words";
      words: PerWordStyle[];
      blockOpacity: number;
      blockTransform: string;
    }
  | {
      kind: "hero";
      word: string;
      index: number;
      total: number;
      opacity: number;
      transform: string;
      letterSpacing?: string;
    };

// ─── Phase + timing helpers ─────────────────────────────────────

interface Phases {
  entrancePhase: number;
  exitPhase: number;
  exitStart: number;
  inExit: boolean;
}

function computePhases(spec: ArchetypeSpec, sceneDuration: number, progress: number): Phases {
  const entrancePhase = Math.min(ENTRANCE_PHASE_CAP, spec.entrance / sceneDuration);
  const exitPhase = Math.min(EXIT_PHASE_CAP, spec.exit / sceneDuration);
  const exitStart = 1 - exitPhase;
  return { entrancePhase, exitPhase, exitStart, inExit: progress >= exitStart };
}

function rawEntrance(progress: number, entrancePhase: number, startAt = ENTRANCE_START): number {
  return interpolate(progress, [startAt, startAt + entrancePhase], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
}

function rawExit(progress: number, exitStart: number): number {
  if (progress < exitStart) return 0;
  return interpolate(progress, [exitStart, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
}

// Normalized hold time 0→1 over the hold phase; 0 outside.
function holdT(
  progress: number,
  entrancePhase: number,
  exitStart: number,
  startAt = ENTRANCE_START,
): number {
  const holdStart = startAt + entrancePhase;
  if (progress < holdStart || progress > exitStart || exitStart <= holdStart) return 0;
  return (progress - holdStart) / (exitStart - holdStart);
}

// Sine breathe — returns offset around 0; magnitude is peak-to-peak.
function breathe(t: number, magnitude: number, cycles = 1): number {
  return (Math.sin(t * Math.PI * 2 * cycles) * magnitude) / 2;
}

// ─── Renderer ───────────────────────────────────────────────────

export function renderArchetype(
  archetypeRaw: TextArchetype | string | undefined,
  progress: number,
  scale: number,
  text: string,
  sceneDuration: number,
): ArchetypeRender {
  const archetype = normalizeArchetype(archetypeRaw);
  const spec = ARCHETYPE_SPECS[archetype];
  const phases = computePhases(spec, sceneDuration, progress);

  switch (archetype) {
    case "subtle":
      return renderSubtle(progress, scale, text, phases);
    case "typewriter":
      return renderTypewriter(progress, scale, text, phases, sceneDuration);
    case "wordStagger":
      return renderWordStagger(progress, scale, text, phases, sceneDuration);
    case "slam":
      return renderSlam(progress, scale, text, phases);
    case "cinematic":
      return renderCinematic(progress, scale, text, phases);
    case "heroWord":
      return renderHeroWord(progress, text, phases);
  }
}

// ─── subtle ─────────────────────────────────────────────────────
// Pure fade in / fade out — true to the name. No translation, no breathe,
// no transition jump. The supporting caption that doesn't compete with the
// visual. Only thing animating is opacity.
function renderSubtle(
  progress: number,
  _scale: number,
  text: string,
  phases: Phases,
): ArchetypeRender {
  const raw = rawEntrance(progress, phases.entrancePhase);
  const ex = rawExit(progress, phases.exitStart);

  const opacityIn = Easing.out(Easing.cubic)(raw);
  const opacityOut = 1 - Easing.in(Easing.cubic)(ex);
  const opacity = opacityIn * (phases.inExit ? opacityOut : 1);

  return {
    kind: "block",
    block: {
      opacity,
      transform: "none",
    },
    text,
  };
}

// ─── typewriter ─────────────────────────────────────────────────
// Char reveal with deterministic cursor blink. Exit slides each char off
// the left edge in reading order — same cascade pattern as wordStagger
// (top line clears first by virtue of reading-order index ascending).
function renderTypewriter(
  progress: number,
  scale: number,
  text: string,
  phases: Phases,
  sceneDuration: number,
): ArchetypeRender {
  const raw = rawEntrance(progress, phases.entrancePhase);

  // Constant typing pace — linear, no easing. Decelerating eases make the
  // last chars feel sluggish, which kills the typewriter rhythm.
  const visibleChars = Math.max(0, Math.floor(raw * text.length));

  // Time-based 1.5Hz blink (OS terminal convention). Stays consistent
  // regardless of scene length.
  const seconds = progress * sceneDuration;
  const cursorOn = Math.sin(seconds * Math.PI * 3) > 0;
  const stillTyping = visibleChars < text.length;

  // Entry opacity ramps fast (we want chars solid as they appear).
  const opacityIn = Math.min(1, raw * 8);

  // Cursor visible during typing and the tail of the hold; gone on exit.
  const cursor = cursorOn && (stillTyping || (!phases.inExit && opacityIn > 0.5));

  // Per-character exit cascade — slides each char left, staggered by
  // reading-order index. Compresses if the exit window can't fit the full
  // sequence (very long text on a short scene).
  let charExits: { opacity: number; translateX: number }[] | undefined;
  if (phases.inExit && text.length > 0) {
    const STAGGER_OUT = 0.025;
    const PER_CHAR_OUT = 0.30;
    const SLIDE_LEFT_DISTANCE = 350 * scale;
    const actualExitSec = phases.exitPhase * sceneDuration;
    const idealExitSec = (text.length - 1) * STAGGER_OUT + PER_CHAR_OUT;
    const outScale = Math.min(1, actualExitSec / idealExitSec);
    const stagOutNorm = (STAGGER_OUT * outScale) / sceneDuration;
    const perCharOutNorm = (PER_CHAR_OUT * outScale) / sceneDuration;

    charExits = Array.from({ length: text.length }, (_, i) => {
      const charExitStart = phases.exitStart + i * stagOutNorm;
      const charExitEnd = charExitStart + perCharOutNorm;
      const charExitRaw = interpolate(progress, [charExitStart, charExitEnd], [0, 1], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });
      const charExitEased = Easing.in(Easing.cubic)(charExitRaw);
      return {
        opacity: 1 - charExitEased,
        translateX: -charExitEased * SLIDE_LEFT_DISTANCE,
      };
    });
  }

  return {
    kind: "typewriter",
    visibleChars,
    cursor,
    opacity: opacityIn,
    transform: "none",
    charExits,
  };
}

// ─── wordStagger ────────────────────────────────────────────────
// Dynamic entrance: total time depends on word count (more words = more
// time to read each one), bounded so it doesn't run forever on long scenes
// or get crammed on short ones. As the NEXT word arrives, prior words dim
// to ~45% opacity — the kinetic-typography "active word" focus.
// Exit slides each word off the left edge in reading order. Words wrap via
// CSS so we never know line breaks at render time, but indices ARE in
// reading order — staggering by index gives a top-line-first cascade for
// free: words on line 1 occupy the lowest indices, so they exit before
// any word on line 2.
function renderWordStagger(
  progress: number,
  scale: number,
  text: string,
  phases: Phases,
  sceneDuration: number,
): ArchetypeRender {
  const words = text.split(/\s+/).filter(Boolean);
  const wordCount = Math.max(words.length, 1);

  // Per-word timing constants (seconds). Min/max stagger keeps the cadence
  // in the Hollywood-typography sweet spot (~280–450ms per word land)
  // regardless of scene length.
  const STAGGER_MIN = 0.28;
  const STAGGER_MAX = 0.45;
  const PER_WORD_ANIM = 0.5;

  // Floor entrance using the minimum stagger.
  const minEntrance = (wordCount - 1) * STAGGER_MIN + PER_WORD_ANIM;

  // Target: ~55% of the scene for entrance, so longer scenes get a longer
  // build-up. Without this the entrance feels rushed against the long hold.
  const TARGET_ENTRANCE_FRACTION = 0.55;
  const targetEntrance = sceneDuration * TARGET_ENTRANCE_FRACTION;

  // Ceiling: leave room for exit + meaningful hold so the FINAL word sits
  // as the focal point.
  const exitSec = ARCHETYPE_SPECS.wordStagger.exit;
  const minHold = 0.5;
  const maxEntrance = Math.max(0.6, sceneDuration - exitSec - minHold);

  // Pick proportional target, bounded by [minEntrance, maxEntrance].
  let entranceSec = Math.min(maxEntrance, Math.max(minEntrance, targetEntrance));

  // Cap the implied per-word stagger at STAGGER_MAX so words don't sit too
  // long between lands on very long scenes.
  if (wordCount > 1) {
    const impliedStagger = (entranceSec - PER_WORD_ANIM) / (wordCount - 1);
    if (impliedStagger > STAGGER_MAX) {
      entranceSec = (wordCount - 1) * STAGGER_MAX + PER_WORD_ANIM;
    }
  }

  // Recompute phases for this archetype (overrides default phases).
  const entrancePhase = entranceSec / sceneDuration;
  const exitPhase = Math.min(0.4, exitSec / sceneDuration);
  const exitStart = 1 - exitPhase;

  // Word entrance window: each word's own animation gets PER_WORD_ANIM
  // seconds, the rest of entrancePhase is the staggered offset distribution.
  const staggerIn =
    wordCount > 1 ? (entranceSec - PER_WORD_ANIM) / (wordCount - 1) / sceneDuration : 0;
  const wordEntranceDur = PER_WORD_ANIM / sceneDuration;

  // Per-word exit cadence. STAGGER_OUT is short so words within a single
  // wrapped line clear nearly together — the perceived gap between lines
  // comes from the words *between* line breaks, not the per-word delay.
  // Compress proportionally if the scene's exit window can't fit the full
  // cascade (e.g. very short scene with many words).
  const STAGGER_OUT = 0.06;
  const PER_WORD_OUT = 0.32;
  const SLIDE_LEFT_DISTANCE = 350 * scale;
  const actualExitSec = exitPhase * sceneDuration;
  const idealExitSec = (wordCount - 1) * STAGGER_OUT + PER_WORD_OUT;
  const outScale = Math.min(1, actualExitSec / idealExitSec);
  const stagOutNorm = (STAGGER_OUT * outScale) / sceneDuration;
  const perWordOutNorm = (PER_WORD_OUT * outScale) / sceneDuration;

  const ht = holdT(progress, entrancePhase, exitStart);

  // Active-word focus: previous words dim to ACTIVE_DIM as the next word
  // arrives — reads as a "grey" handoff via opacity reduction, directs
  // attention to the latest word without making prior ones unreadable.
  // Bumped from 0.70 → 0.85: 70% became muddy on busy photo backgrounds
  // (especially mid-tone areas where the dimmed white blends into the bg).
  // 85% keeps the active-word hierarchy while staying legible on media.
  const ACTIVE_DIM = 0.85;

  const perWord = words.map((w, i) => {
    // Entrance window for THIS word
    const wordStart = ENTRANCE_START + i * staggerIn;
    const wordEnd = wordStart + wordEntranceDur;
    const wordRaw = interpolate(progress, [wordStart, wordEnd], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
    const sp = spring(wordRaw, SPRING_CRISP);
    const yIn = interpolate(sp, [0, 1], [55 * scale, 0]);
    const rotIn = interpolate(sp, [0, 1], [-3, 0]);
    const opacityIn = Math.min(1, wordRaw * 7);

    // Subtle hold breathe (won't even register but keeps each word "alive")
    const yBreathe = breathe(ht, 1 * scale, 1) * Math.cos((i / wordCount) * Math.PI);

    // Dim instantly when the NEXT word starts entering — tiny 50ms ramp so
    // the transition isn't a hard cut, but visually reads as "snaps to grey
    // the moment the new word appears."
    let dimProgress = 0;
    if (i < words.length - 1) {
      const nextStart = ENTRANCE_START + (i + 1) * staggerIn;
      const SNAP_RAMP = 0.02; // ~50ms at 2.5s scene
      dimProgress = interpolate(progress, [nextStart, nextStart + SNAP_RAMP], [0, 1], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });
    }
    const focusOpacity = 1 - dimProgress * (1 - ACTIVE_DIM);

    // Per-word exit: each word starts sliding left at exitStart + i*stagOut,
    // accelerates with ease-in-cubic so it feels yanked off-frame.
    const wordExitStart = exitStart + i * stagOutNorm;
    const wordExitEnd = wordExitStart + perWordOutNorm;
    const wordExitRaw = interpolate(progress, [wordExitStart, wordExitEnd], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
    const wordExitEased = Easing.in(Easing.cubic)(wordExitRaw);
    const exitX = -wordExitEased * SLIDE_LEFT_DISTANCE;
    const isExiting = wordExitRaw > 0;

    // Final composition
    const opacity = opacityIn * focusOpacity * (1 - wordExitEased);
    const y = yIn + (isExiting ? 0 : yBreathe);
    const rot = isExiting ? 0 : rotIn;

    return {
      text: w,
      style: {
        opacity,
        transform: `translate(${exitX}px, ${y}px) rotate(${rot}deg)`,
      },
    };
  });

  return {
    kind: "words",
    words: perWord,
    blockOpacity: 1,
    blockTransform: "none",
  };
}

// ─── slam ──────────────────────────────────────────────────
// In-place impact, NOT a depth/zoom motion (cinematic already owns that
// lane). Word appears at readable size and HITS — drama lives in the
// squash-and-stretch arc:
//   approach pose (vertically stretched, scaleY > 1, scaleX < 1)
//   → impact (violent horizontal pancake, scaleX 1.22 / scaleY 0.74,
//     frame shake + letter crunch firing simultaneously)
//   → rebound (counter-stretched scaleY 1.12 / scaleX 0.94)
//   → damped settle to 1.0
// No vertical translation — the squash arc + camera shake + tilt kick
// carry the impact without any top-to-bottom drop.
function renderSlam(
  progress: number,
  scale: number,
  text: string,
  phases: Phases,
): ArchetypeRender {
  const raw = rawEntrance(progress, phases.entrancePhase);
  const ex = rawExit(progress, phases.exitStart);
  const ht = holdT(progress, phases.entrancePhase, phases.exitStart);

  // Squash-and-stretch arc. Keyframes (raw): 0 = approach pose, 0.30 =
  // impact, 0.45 = rebound, 0.60 = secondary oscillation, 1.0 = rest.
  // scaleX/scaleY are anti-correlated at every keyframe — that's what
  // sells "weight" vs. cinematic's uniform scale collapse.
  const sxIn = interpolate(raw, [0, 0.30, 0.45, 0.60, 1.0], [0.92, 1.22, 0.94, 1.02, 1.0]);
  const syIn = interpolate(raw, [0, 0.30, 0.45, 0.60, 1.0], [1.18, 0.74, 1.12, 0.99, 1.0]);
  // Tilt-and-correct: small entry tilt, levels at impact, micro overshoot.
  const rotIn = interpolate(raw, [0, 0.30, 0.45, 1.0], [-1.5, 0, 0.8, 0]);
  // Transient letter crunch AT impact, releases open by rebound. Distinct
  // from cinematic's wide→tight gradual tracking collapse.
  const lsInEm = interpolate(raw, [0, 0.20, 0.30, 0.45, 1.0], [0, -0.04, -0.06, 0, 0]);

  // Camera shake — full intensity at impact, fast decay over the next 20%
  // of entrance. Sin/cos at offset frequencies feel noisy while staying
  // deterministic for export.
  const shakeWindow = Math.max(0, 1 - Math.max(0, raw - 0.30) / 0.20);
  const shakeX = Math.sin(raw * 70) * 14 * scale * shakeWindow;
  const shakeY = Math.cos(raw * 80) * 10 * scale * shakeWindow;

  // Punchy opacity ramp so text is solid through the size change.
  const opacityIn = Math.min(1, raw * 8);

  // Hold: gentle 0.8% uniform scale breathe.
  const sBreathe = 1 + breathe(ht, 0.008, 1);

  // Exit: ease-in-expo shrink + late-bias fade — decisive leave.
  const easedExit = Easing.in(Easing.exp)(ex);
  const sOut = interpolate(easedExit, [0, 1], [1, 0.85]);
  const opacityOut = interpolate(ex, [0, 0.55, 1], [1, 0.8, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const sx = phases.inExit ? sOut : sxIn * sBreathe;
  const sy = phases.inExit ? sOut : syIn * sBreathe;
  const tx = phases.inExit ? 0 : shakeX;
  const ty = phases.inExit ? 0 : shakeY;
  const rot = phases.inExit ? 0 : rotIn;
  const ls = phases.inExit ? 0 : lsInEm;
  const opacity = opacityIn * (phases.inExit ? opacityOut : 1);

  return {
    kind: "block",
    block: {
      opacity,
      transform: `translate(${tx}px, ${ty}px) rotate(${rot}deg) scale(${sx}, ${sy})`,
      letterSpacing: `${ls}em`,
    },
    text,
  };
}

// ─── cinematic ──────────────────────────────────────────────────
// Hollywood Movie-Trailer FlyIn (vuild-style without filter:blur).
// Entry: ease-out-circ — weighty deceleration, classic cinema arrival.
//        Scale 3.0 → 1.0, tracking +40 → 0 (letters wide-spaced from depth
//        collapse to readable). Slow opacity ramp finishes by progress 0.4
//        so text becomes "real" as it nears the camera plane.
// Hold:  ±0.6px tracking wobble + 1% scale breathe.
// Exit:  ease-in-expo — text holds, then RECEDES into the background.
//        Scale 1.0 → 0.4 (zooms out / shrinks away), tracking spreads back
//        out (0 → +24) like objects dissipating into the distance, opacity
//        holds high then drops late so the recede motion stays visible.
function renderCinematic(
  progress: number,
  scale: number,
  text: string,
  phases: Phases,
): ArchetypeRender {
  const raw = rawEntrance(progress, phases.entrancePhase);
  const ex = rawExit(progress, phases.exitStart);

  // Entry: ease-out-circle — slow start (text far away), strong deceleration into place
  const easedIn = Easing.out(Easing.circle)(raw);
  const sIn = interpolate(easedIn, [0, 1], [3.0, 1]);
  const yIn = interpolate(easedIn, [0, 1], [18 * scale, 0]);
  // Slow opacity ramp — text becomes "real" only as it approaches the camera
  const opacityIn = interpolate(raw, [0, 0.4], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // No hold-phase breathing — subpixel rendering on tiny scale changes
  // reads as jitter on stable text. Cinematic holds dead-still during the
  // visible phase.

  // Exit: ease-in-expo — held, then RECEDES into the background
  const easedExit = Easing.in(Easing.exp)(ex);
  const sOut = interpolate(easedExit, [0, 1], [1, 0.4]);
  // Subtle drift back/up to reinforce "going away"
  const yOut = interpolate(easedExit, [0, 1], [0, -10 * scale]);
  // Opacity holds 100% for first 50% of exit, then drops to 0
  const opacityOut = interpolate(ex, [0, 0.5, 1], [1, 0.85, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const s = phases.inExit ? sOut : sIn;
  const y = phases.inExit ? yOut : yIn;
  const opacity = opacityIn * (phases.inExit ? opacityOut : 1);

  // No CSS filter. Earlier iterations layered a ~2.5px gaussian blur at the
  // lifecycle edges for a Hollywood motion-blur feel, but iOS Safari is
  // notoriously bad at compositing `filter` with an animating `transform` —
  // the zoom would stall mid-motion on mobile while desktop and the
  // server-side Puppeteer export rendered fine. The cinematic effect's
  // identity is the scale collapse + slow opacity ramp + ease-out-circ
  // timing, all of which work without the filter. willChange hints both
  // properties are animating so the browser keeps the layer GPU-composited.
  return {
    kind: "block",
    block: {
      opacity,
      transform: `translateY(${y}px) scale(${s})`,
      willChange: "transform, opacity",
    },
    text,
  };
}

// ─── heroWord ───────────────────────────────────────────────────
// One word at a time, each lands with anticipation overshoot. Mid-sequence
// words hand off with brief brightness flash before fade. Final word's exit
// participates in the global exit window — scales up + fades for the finale.
function renderHeroWord(
  progress: number,
  text: string,
  phases: Phases,
): ArchetypeRender {
  const words = text.split(/\s+/).filter(Boolean);
  if (words.length === 0) {
    return { kind: "hero", word: "", index: 0, total: 0, opacity: 0, transform: "scale(1)" };
  }

  // Words occupy the time between entrance start and exit start.
  const sequenceStart = ENTRANCE_START + phases.entrancePhase * 0.2;
  const sequenceEnd = phases.exitStart;
  const sequenceDur = Math.max(0.01, sequenceEnd - sequenceStart);
  const slot = sequenceDur / words.length;

  // Determine active word.
  const localProgress = Math.max(0, Math.min(0.999, (progress - sequenceStart) / sequenceDur));
  const idx = Math.min(words.length - 1, Math.floor(localProgress / (1 / words.length)));
  const local = (localProgress * words.length) - idx;
  const isLast = idx === words.length - 1;

  // Per-word entrance: anticipation + spring overshoot
  const ENTER_FRAC = 0.28;
  const HOLD_FRAC = 0.55;
  const HANDOFF_FRAC = 0.85;

  let scale: number;
  let opacity: number;

  if (local < ENTER_FRAC) {
    const entRaw = local / ENTER_FRAC;
    const sp = spring(entRaw, SPRING_CRISP);
    // Overshoot: 0.5 → 1.06 → 1.0
    scale = sp < 0.7 ? interpolate(sp, [0, 0.7], [0.5, 1.06]) : interpolate(sp, [0.7, 1], [1.06, 1.0]);
    opacity = Math.min(1, entRaw * 6);
  } else if (local < HOLD_FRAC) {
    // Hold: 0.5% breathe per word
    const ht = (local - ENTER_FRAC) / (HOLD_FRAC - ENTER_FRAC);
    scale = 1 + breathe(ht, 0.01, 1);
    opacity = 1;
  } else if (local < HANDOFF_FRAC && !isLast) {
    // Brief brightness pulse + fade for handoff to next word
    const handoffRaw = (local - HOLD_FRAC) / (HANDOFF_FRAC - HOLD_FRAC);
    scale = interpolate(handoffRaw, [0, 1], [1, 1.04]);
    // Pulse: 1 → 1.15 (brightness via opacity > 1 is faked by holding 1) → fade
    opacity = handoffRaw < 0.3 ? 1 : interpolate(handoffRaw, [0.3, 1], [1, 0]);
  } else if (!isLast) {
    // Trailing nothing-frame for non-last words
    scale = 1.04;
    opacity = 0;
  } else {
    // Last word: hold until global exit kicks in
    scale = 1;
    opacity = 1;
  }

  // Last word participates in the global exit — simple fast fade with a
  // tiny scale lift. No anticipation, no tracking compression: the goal is
  // to give the WORDS the most time, not the exit animation.
  if (isLast && phases.inExit) {
    const ex = rawExit(progress, phases.exitStart);
    const easedExit = Easing.in(Easing.cubic)(ex);
    scale = interpolate(easedExit, [0, 1], [1, 1.08]);
    opacity = 1 - easedExit;
  }

  return {
    kind: "hero",
    word: words[idx],
    index: idx,
    total: words.length,
    opacity,
    transform: `scale(${scale})`,
  };
}

// ─── Effect duration helpers ────────────────────────────────────
//
// Per-archetype min/max DURATION (seconds) — the time the effect itself
// uses, not the scene length. On long scenes the effect runs at most for
// `maxDuration` and then disappears, signaling the AI to fill the rest
// with another effect.
//
//  - minDurationFor(archetype, text): minimum effect duration accounting
//    for text length (text-dependent archetypes scale up).
//  - effectiveDuration(archetype, text, sceneDuration): how long the
//    effect actually runs in the given scene — bounded by [minFor, max].
//  - canFit(items, sceneSeconds): whether a sequence of (archetype, text)
//    plays fits within a scene.

const TYPEWRITER_SEC_PER_CHAR = 0.08; // matches the linear char reveal pace
const HEROWORD_PER_WORD_SLOT = 0.6; // each word in heroWord needs ~0.6s on screen
const WORDSTAGGER_MIN_HOLD = 0.5; // matches renderWordStagger's minHold

/**
 * Compute the minimum DURATION (seconds) the effect needs for this text.
 * Text-dependent archetypes scale up; others return their static
 * spec.minDuration.
 */
export function minDurationFor(archetype: TextArchetype, text: string): number {
  const spec = ARCHETYPE_SPECS[archetype];
  const wordCount = Math.max(1, text.split(/\s+/).filter(Boolean).length);

  switch (archetype) {
    case "typewriter": {
      const revealSec = Math.max(0.6, text.length * TYPEWRITER_SEC_PER_CHAR);
      return revealSec + 0.3 + spec.exit;
    }
    case "wordStagger": {
      return (wordCount - 1) * 0.28 + 0.5 + WORDSTAGGER_MIN_HOLD + spec.exit;
    }
    case "heroWord": {
      return wordCount * HEROWORD_PER_WORD_SLOT + spec.exit;
    }
    default:
      return spec.minDuration;
  }
}

/**
 * How long the effect actually runs inside a given scene. The effect uses
 * at most spec.maxDuration; if the scene is shorter than that, it uses
 * the scene length; if the text needs more (long typewriter, many words),
 * the minimum wins.
 *
 * On long scenes, sceneDuration > effectiveDuration(...) means the AI
 * has remaining time to fill with another effect.
 */
export function effectiveDuration(
  archetype: TextArchetype,
  text: string,
  sceneDuration: number,
): number {
  const spec = ARCHETYPE_SPECS[archetype];
  const minFor = minDurationFor(archetype, text);
  const cappedMax = Math.max(spec.maxDuration, minFor);
  return Math.min(sceneDuration, cappedMax);
}

export interface ArchetypePlay {
  archetype: TextArchetype;
  text: string;
}

/**
 * Whether a sequence of archetype plays fits in the given scene duration.
 * Used by the AI/tool layer to validate before committing to a plan.
 *
 * @example
 *   canFit(
 *     [
 *       { archetype: "subtle", text: "Hi" },
 *       { archetype: "heroWord", text: "Launch" },
 *     ],
 *     4.0,
 *   ); // → true if both fit; false otherwise
 */
export function canFit(items: ArchetypePlay[], sceneSeconds: number): boolean {
  const total = items.reduce(
    (sum, item) => sum + minDurationFor(item.archetype, item.text),
    0,
  );
  return total <= sceneSeconds;
}

/**
 * Total minimum seconds for a sequence — useful when canFit returns false
 * and you need to know how much time is missing.
 */
export function totalMinDurationFor(items: ArchetypePlay[]): number {
  return items.reduce(
    (sum, item) => sum + minDurationFor(item.archetype, item.text),
    0,
  );
}
